INSERT  IGNORE INTO `feedbacks` (`feedback_id`, `rating`, `content`, `status`, `manager_note`, `created_at`, `resolved_at`, `customer_id`, `handled_by`, `product_id`) VALUES (1,1,'Áo bị phai màu sau vài lần giặt. Tư vấn rõ ràng và phù hợp trình độ chơi. Lần mua 01.','NEW',NULL,'2026-10-23 16:26:11',NULL,6,NULL,40),(2,2,'Nhiều quả bay lắc, không đều. Mong có ưu đãi giá cho câu lạc bộ. Lần mua 02.','NEW',NULL,'2026-10-22 16:26:11',NULL,7,NULL,39),(3,3,'Giày đẹp nhưng hơi chật phần mũi. Giao hàng chậm hơn lịch hẹn một ngày. Lần mua 03.','NEW',NULL,'2026-10-21 16:26:11',NULL,8,NULL,38),(4,4,'Vợt đầm tay, đánh cầu cao sâu rất dễ. Dịch vụ đan cước đúng số kg đã yêu cầu. Lần mua 04.','NEW',NULL,'2026-10-20 16:26:11',NULL,9,NULL,36),(5,5,'Khung vợt chắc, đập cầu uy lực, rất hài lòng. Đổi trả được hướng dẫn rõ ràng. Lần mua 05.','NEW',NULL,'2026-10-19 16:26:11',NULL,10,NULL,34),(6,1,'Giao sai màu so với đơn đặt hàng, mong shop đổi lại. Mong có thêm phụ kiện tặng kèm. Lần mua 06.','NEW',NULL,'2026-10-18 16:26:11',NULL,11,NULL,33),(7,2,'Vợt bị nứt khung sau một tháng sử dụng. Tư vấn rõ ràng và phù hợp trình độ chơi. Lần mua 07.','NEW',NULL,'2026-10-17 16:26:11',NULL,12,NULL,37),(8,3,'Đánh được, tuy nhiên cán hơi to so với tay mình. Mong có ưu đãi giá cho câu lạc bộ. Lần mua 08.','NEW',NULL,'2026-10-16 16:26:11',NULL,13,NULL,35),(9,4,'Cầu bay ổn định, bền, đánh được nhiều trận. Giao hàng chậm hơn lịch hẹn một ngày. Lần mua 09.','RESOLVED','Đã liên hệ, tư vấn và thống nhất phương án hỗ trợ khách hàng.','2026-10-15 16:26:11','2026-11-01 16:26:11',14,5,15),(10,5,'Vợt đầm tay, đánh cầu cao sâu rất dễ. Dịch vụ đan cước đúng số kg đã yêu cầu. Lần mua 10.','RESOLVED','Đã liên hệ, tư vấn và thống nhất phương án hỗ trợ khách hàng.','2026-10-14 16:26:11','2026-10-31 16:26:11',15,3,11),(11,1,'Áo bị phai màu sau vài lần giặt. Đổi trả được hướng dẫn rõ ràng. Lần mua 11.','RESOLVED','Đã liên hệ, tư vấn và thống nhất phương án hỗ trợ khách hàng.','2026-10-13 16:26:11','2026-11-04 16:26:11',16